W, H = 780, 350
CELL = 15; G = 14; TOP = 46
def svg(th, acc):
    ink, mut, grid, surf = th
    o = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" font-family="Arial,Helvetica,sans-serif" role="img">']
    o.append(f'<rect width="{W}" height="{H}" fill="{surf}"/>')
    titles = {"0,0": "Query patch: row 1, column 1", "7,7": "Query patch: row 8, column 8", "3,10": "Query patch: row 4, column 11"}
    for k, (key, m) in enumerate(MAPS.items()):
        x0 = 30 + k * 250; qr, qc = map(int, key.split(","))
        o.append(f'<text x="{x0 + G*CELL/2}" y="{TOP-14}" fill="{ink}" font-size="14" text-anchor="middle">{titles[key]}</text>')
        for r in range(G):
            for c in range(G):
                v = max(0.0, min(1.0, m[r][c]))
                o.append(f'<rect x="{x0+c*CELL}" y="{TOP+r*CELL}" width="{CELL}" height="{CELL}" fill="{acc}" fill-opacity="{v:.2f}" stroke="{grid}" stroke-width="0.5"/>')
        o.append(f'<rect x="{x0+qc*CELL}" y="{TOP+qr*CELL}" width="{CELL}" height="{CELL}" fill="none" stroke="{ink}" stroke-width="2.5"/>')
    # colour key
    ky = TOP + G*CELL + 30; kx = 250
    o.append(f'<text x="{kx-10}" y="{ky+12}" fill="{mut}" font-size="13" text-anchor="end">cosine similarity  0 or less</text>')
    for i in range(11):
        o.append(f'<rect x="{kx+i*24}" y="{ky}" width="24" height="16" fill="{acc}" fill-opacity="{i/10:.1f}" stroke="{grid}" stroke-width="0.5"/>')
    o.append(f'<text x="{kx+11*24+10}" y="{ky+12}" fill="{mut}" font-size="13">1</text>')
    o.append(f'<text x="{W/2}" y="{ky+44}" fill="{ink}" font-size="13" text-anchor="middle">Outlined cell: the query patch. Shading: how similar each other patch\'s position vector is to it.</text>')
    o.append('</svg>'); return "\n".join(o)
light = ('#0b1a33', '#4a5b78', '#dde5f2', '#ffffff')
dark = ('#e8eefc', '#9fb0cf', '#22355a', '#0b162d')
open(sys.argv[1] + '.svg', 'w').write(svg(light, '#2a78d6'))
open(sys.argv[1] + '-dark.svg', 'w').write(svg(dark, '#3987e5'))
